window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-97a84e8ffd81df97"]={"versions": [{"id": "FIG-97a84e8ffd81df97", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Pwm_DeInit()</code>) zur Spezifikation des De-Initialisierungsablaufs des PWM-Treibers innerhalb der AUTOSAR-Basissoftware (MCAL).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Pwm User</strong>: Oberhalb des PWM-Treibers angesiedelte Software-Einheit bzw. Komponente, die den Treiber nutzt und de-initialisiert.\n</li><li><strong>PWM Driver</strong>: Basissoftware-Treibermodul zur Pulsweitenmodulation (MCAL).\n</li><li><strong>Pwm_DeInit</strong>: Synchrone Treiberschnittstelle zur De-Initialisierung des PWM-Moduls.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Aufrufer <code>Pwm User</code> ruft synchron die Operation <code>Pwm_DeInit</code> auf dem <code>PWM Driver</code> auf.\n</li><li>Der Treiber führt die De-Initialisierungssequenz aus.\n</li><li>Der <code>PWM Driver</code> kehrt mit einer unbenannten Rückkehrnachricht (<code>return</code>) zum Aufrufer zurück.\n</li><li>Nach dem Aufruf befinden sich die PWM-Ausgangskanäle im Ruhezustand (idle state).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die De-Initialisierung überführt alle PWM-Kanäle deterministisch in einen definierten Idle-Zustand. Der Aufruf erfolgt synchron und blockierend bis zur Rückkehr zum Aufrufer.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-44738415f7b37da9", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Pwm_DeInit()</code>) zur Spezifikation des De-Initialisierungsablaufs des PWM-Treibers innerhalb der AUTOSAR-Basissoftware (MCAL).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Generic Elements::Pwm User</strong>: Generisches BSW- oder Anwenderelement, das die PWM-Treiberschnittstelle nutzt.\n</li><li><strong>«module» Pwm::Pwm</strong>: AUTOSAR-BSW-Modul der MCAL-Schicht.\n</li><li><strong>Pwm_DeInit()</strong>: Synchrone C-Funktionsschnittstelle zur De-Initialisierung.\n</li><li><strong>Pwm_DeInit</strong>: Rückkehrnachricht der De-Initialisierungsoperation.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>Generic Elements::Pwm User</code> sendet den synchronen Aufruf <code>Pwm_DeInit()</code> an das Modul <code>Pwm::Pwm</code>.\n</li><li>Während der Ausführung werden die PWM-Ausgangskanäle in den per Konfiguration definierten Zustand überführt.\n</li><li>Das Modul bestätigt den Abschluss über den Rückkehrpfeil <code>Pwm_DeInit</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Zustand der PWM-Ausgangskanäle nach der De-Initialisierung ist nicht zwingend der Idle-Zustand, sondern wird über die Modulkonfiguration festgelegt. Die Spezifikation ist mit dem Bearbeitungsstatus <code>proposed by DB as per SWS Pwm Driver 1.0.9</code> annotiert.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-8e2937ffd81a0a5e", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Pwm_DeInit()</code>) zur Spezifikation des De-Initialisierungsablaufs des PWM-Treibers innerhalb der AUTOSAR-Basissoftware (MCAL).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Pwm User</strong>: Oberhalb liegender BSW- oder Anwendungskontext des PWM-Treibers.\n</li><li><strong>«module» Pwm</strong>: AUTOSAR-BSW-Modul der MCAL-Schicht.\n</li><li><strong>Pwm_DeInit()</strong>: Synchrone Treiberschnittstelle zur De-Initialisierung des Moduls sowie Bezeichnung der Rückkehrsequenz.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>Pwm User</code> setzt den synchronen Aufruf <code>Pwm_DeInit()</code> an das Modul <code>Pwm</code> ab.\n</li><li>Das Modul de-initialisiert die Hardware und versetzt die PWM-Ausgangskanäle in den konfigurierten Zustand.\n</li><li>Die De-Initialisierung schließt mit der Rückkehrnachricht <code>Pwm_DeInit()</code> ab.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Zustand der PWM-Ausgangskanäle nach der De-Initialisierung ist nicht zwingend der Idle-Zustand, sondern wird über die Modulkonfiguration festgelegt. Die Spezifikation ist mit dem Bearbeitungsstatus <code>proposed by DB as per SWS Pwm Driver 1.0.9</code> annotiert.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-97a84e8ffd81df97", "to": "FIG-44738415f7b37da9", "fr": "R2.1.20", "tr": "R3.0.7", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Lebenslinie / Aufrufer</strong>: Umbenennung von <code>Pwm User</code> zu <code>Generic Elements::Pwm User</code>.\n</li><li><strong>Lebenslinie / Modul</strong>: Umbenennung von <code>PWM Driver</code> zu <code>«module» Pwm::Pwm</code> mit Subsystem-/Modulsymbol.\n</li><li><strong>Synchroner Aufruf</strong>: Methodenaufruf mit Klammern präzisiert (<code>Pwm_DeInit()</code> statt <code>Pwm_DeInit</code>).\n</li><li><strong>Rückkehrnachricht</strong>: Explizite Beschriftung <code>Pwm_DeInit</code> statt <code>return</code>.\n</li><li><strong>Zustand nach De-Initialisierung</strong>: Semantische Änderung der Nachbedingung von festem Ruhezustand („The PWM output channels are in idle state.“) zu konfigurierbarem Zustand („The PWM output channels are in the state defined by configuration.“).\n</li><li><strong>Metadaten/Notizfeld</strong>: Ergänzung des strukturierten Notizblocks mit <code>Status: proposed by DB as per SWS Pwm Driver 1.0.9</code>, <code>Description:</code> und <code>Comments:</code>.\n</li></ul>"}, {"from": "FIG-44738415f7b37da9", "to": "FIG-8e2937ffd81a0a5e", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Lebenslinie / Aufrufer</strong>: Vereinfachung des Namens von <code>Generic Elements::Pwm User</code> zu <code>Pwm User</code>.\n</li><li><strong>Lebenslinie / Modul</strong>: Entfernung des Paket-Namespace-Präfix (<code>Pwm</code> statt <code>Pwm::Pwm</code>).\n</li><li><strong>Rückkehrnachricht</strong>: Signaturbezeichnung mit Klammern vereinheitlicht (<code>Pwm_DeInit()</code> statt <code>Pwm_DeInit</code>).\n</li></ul>"}]};
